import * as T from 'three';
export const CONDITIONS={well:'可自行行動',serious:'重傷',unconscious:'昏迷',ohca:'OHCA'};
export const ZONES={front:'前側房間',rear:'後側房間',balcony:'前側陽台／一樓入口'};
export function patientPosition(p){const y=(p.floor-1)*3.2+.31;return [p.zone==='balcony'?1.4:p.x,p.zone==='balcony'?(p.floor===1?.175:(p.floor-1)*3.2+.97):y,p.zone==='balcony'?(p.floor===1?5.4:4.55):p.zone==='rear'?-2.2:1.6];}
export function createPatients(scene,{log,isEnded,focus}){
 const root=new T.Group();root.name='可配置住戶';scene.add(root);const records=[],models=new Map();let nextId=1,selected=null;
 const mat=c=>new T.MeshStandardMaterial({color:c,roughness:.8});const skin=mat('#b98c70'),pants=mat('#303947'),hair=mat('#252626');
 function make(p){const group=new T.Group(),body=new T.Group();group.add(body);root.add(group);const shirt=mat(p.sex==='male'?'#497bad':'#a46a99');function box(w,h,d,x,y,z,m){const o=new T.Mesh(new T.BoxGeometry(w,h,d),m);o.position.set(x,y,z);o.castShadow=true;body.add(o);return o}box(.38,.58,.25,0,1.04,0,shirt);const legs=[];for(const x of [-.12,.12]){legs.push(box(.15,.72,.18,x,.38,0,pants));box(.18,.1,.29,x,.05,-.05,pants)}const head=new T.Mesh(new T.SphereGeometry(.17,12,8),skin);head.position.y=1.52;body.add(head);box(.31,.12,.28,0,1.65,.025,hair);const skirt=new T.Mesh(new T.CylinderGeometry(.23,.39,.55,20),shirt);skirt.position.y=.72;skirt.name='女性裙裝';body.add(skirt);const longHair=box(.34,.42,.18,0,1.4,.13,hair);longHair.name='女性髮型';const arms=[-.27,.27].map(x=>box(.13,.58,.15,x,1.02,0,shirt));return {group,body,shirt,arms,skirt,longHair,legs};}
 function pose(p){let m=models.get(p.id);if(!m){m=make(p);models.set(p.id,m)}m.skirt.visible=p.sex==='female';m.longHair.visible=p.sex==='female';m.legs.forEach(o=>o.material=p.sex==='female'?skin:pants);m.group.name=p.id+' · '+CONDITIONS[p.condition];m.group.position.set(...patientPosition(p));m.group.rotation.y=p.heading*Math.PI/180;m.body.position.set(0,0,0);m.body.rotation.set(0,0,0);m.body.scale.set(1,1,1);m.shirt.color.set(p.sex==='male'?'#497bad':'#a46a99');m.arms.forEach(a=>a.rotation.z=0);
 if(p.condition==='serious'){m.body.scale.y=.62;m.body.rotation.x=.35;m.arms[0].rotation.z=-.6;}
 if(['unconscious','ohca'].includes(p.condition)){m.body.rotation.x=Math.PI/2;m.body.position.z=-.8;if(p.zone==='balcony'&&p.floor>1)m.group.rotation.y=Math.PI/2;}
 m.body.updateWorldMatrix(true,true);const b=new T.Box3().setFromObject(m.body);m.body.position.y+=m.group.position.y-b.min.y;
 }
 const panel=document.createElement('section');panel.className='patient-panel';panel.innerHTML=`<h2>住戶／患者配置</h2><p class="note">以下人數為可配置住戶；另保留雲梯流程的固定待救者 1 人，不列入此表。</p><div class="fire-inputs"><label>男性人數<input id="patientMale" type="number" min="0" max="12" value="0"></label><label>女性人數<input id="patientFemale" type="number" min="0" max="12" value="0"></label></div><button id="patientCount">套用人數</button><p class="patient-feedback" role="status"></p><label for="patientSelect">選擇住戶</label><select id="patientSelect"></select><div class="patient-editor"><div class="fire-inputs"><label>性別<select id="patientSex"><option value="male">男</option><option value="female">女</option></select></label><label>樓層<select id="patientFloor">${[1,2,3,4,5].map(f=>`<option>${f}</option>`).join('')}</select></label></div><label>相對位置<select id="patientZone">${Object.entries(ZONES).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><label>房內左右位置（面向建物正面）<input id="patientX" type="range" min="0.9" max="4.5" step="0.1"></label><label>朝向<select id="patientHeading"><option value="0">朝正面</option><option value="90">朝左</option><option value="180">朝後側</option><option value="270">朝右</option></select></label><label>情境狀態<select id="patientCondition">${Object.entries(CONDITIONS).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><button id="patientApply">套用位置與狀態</button><button id="patientFocus">查看住戶</button></div><p class="note">性別與狀態選擇後立即生效，位置調整請點「套用位置與狀態」。女性為裙裝。「重傷」呈坐倒姿勢；「昏迷」與「OHCA」呈平躺姿勢，請以狀態文字區分。狀態由教官指定，不模擬生理診斷。新增住戶尚未連動搬運或雲梯接人。</p><div class="patient-list"></div>`;
 document.querySelector('.command').prepend(panel);const $=s=>panel.querySelector(s);
 const current=()=>records.find(p=>p.id===selected);
 function form(){const p=current();$('.patient-editor').hidden=!p;if(!p)return;$('#patientSex').value=p.sex;$('#patientFloor').value=p.floor;$('#patientZone').value=p.zone;$('#patientX').value=p.x;$('#patientHeading').value=p.heading;$('#patientCondition').value=p.condition;}
 function render(){const male=records.filter(p=>p.sex==='male').length;$('#patientMale').value=male;$('#patientFemale').value=records.length-male;$('#patientSelect').innerHTML=records.length?records.map(p=>`<option value="${p.id}">${p.id} · ${p.sex==='male'?'男':'女'} · ${p.floor} 樓 · ${CONDITIONS[p.condition]}</option>`).join(''):'<option>尚未配置住戶</option>';$('#patientSelect').value=selected||'';$('.patient-list').innerHTML=records.map(p=>`<p><b>${p.id}</b> ${p.sex==='male'?'男':'女'} · ${p.floor} 樓 ${ZONES[p.zone]} · <strong>${CONDITIONS[p.condition]}</strong></p>`).join('');form();}
 $('#patientSelect').onchange=e=>{selected=e.target.value;form()};
 $('#patientCount').onclick=()=>{if(isEnded())return;const male=$('#patientMale').valueAsNumber,female=$('#patientFemale').valueAsNumber;if(!Number.isInteger(male)||!Number.isInteger(female)||male<0||female<0||male+female>12){$('.patient-feedback').textContent='請輸入非負整數，男女合計最多 12 人。';return}for(const [sex,count] of [['male',male],['female',female]]){let list=records.filter(p=>p.sex===sex);while(list.length>count){const p=list.pop(),m=models.get(p.id);m.group.removeFromParent();m.body.traverse(o=>o.geometry?.dispose());m.shirt.dispose();models.delete(p.id);records.splice(records.indexOf(p),1)}while(list.length<count){const n=records.length,p={id:'住戶 '+String(nextId++).padStart(2,'0'),sex,floor:Math.floor(n/3)+1,zone:'front',x:1.1+(n%3)*1.4,heading:0,condition:'well'};records.push(p);list.push(p);pose(p)}}if(!current())selected=records[0]?.id||null;render();$('.patient-feedback').textContent=`已配置 ${records.length} 人；全場另有固定待救者 1 人。`;log('住戶配置',`可配置住戶：男 ${male} 人、女 ${female} 人`)};
 $('#patientApply').onclick=()=>{if(isEnded())return;const p=current();if(!p)return;const condition=$('#patientCondition').value,zone=$('#patientZone').value;Object.assign(p,{sex:$('#patientSex').value,floor:Number($('#patientFloor').value),zone,x:Number($('#patientX').value),heading:Number($('#patientHeading').value),condition});pose(p);render();$('.patient-feedback').textContent=`已更新 ${p.id}：${p.floor} 樓，${CONDITIONS[p.condition]}`;log('患者調整',`${p.id}／${p.sex==='male'?'男':'女'}／${p.floor} 樓 ${ZONES[p.zone]}／${CONDITIONS[p.condition]}`)};
 $('#patientCondition').onchange=()=>$('#patientApply').onclick();$('#patientSex').onchange=()=>$('#patientApply').onclick();
 $('#patientFocus').onclick=()=>{const p=current();if(p)focus(patientPosition(p))};render();return {root,records,update(){panel.querySelectorAll('input,select,button').forEach(e=>e.disabled=isEnded())}};
}
